from pybricks.hubs import PrimeHub
from pybricks.parameters import Direction, Port, Stop
from pybricks.pupdevices import Motor
from pybricks.robotics import DriveBase

# Set up.
prime_hub = PrimeHub()
left = Motor(Port.B, Direction.COUNTERCLOCKWISE)
right = Motor(Port.F, Direction.CLOCKWISE)
drive_base = DriveBase(left, right, 56, 100)
lower_attachment = Motor(Port.E, Direction.CLOCKWISE)
upper_attachment = Motor(Port.C, Direction.CLOCKWISE)


# The main program starts here.
drive_base.use_gyro(True)
# R south wall of the left home flrst major line from the East right side of the robot
# A Hook in down position
# P 4
lower_attachment.run_angle(500, 180)
drive_base.settings(straight_speed=500)
drive_base.straight(600)
drive_base.turn(-90)
drive_base.straight(-580)
drive_base.straight(580)
drive_base.turn(90)
drive_base.straight(-600)
